(7413906, 1168845, 94815, '<td valign="top">Good focus and light. Royal tint gives this fellow an especially classy look. voted earlier</td>', 'Good focus and light. Royal tint gives this fellow an especially classy look. voted earlier', '2015-11-03 15:53:40.000000', NULL, 1),
(7413907, 1168843, 94815, '<td valign="top">Out of nowhere. Better look twice.</td>', 'Out of nowhere. Better look twice.', '2015-11-03 15:54:26.000000', NULL, 1),
